def plan():
 jobs=[]
 for i,(identity,size,brand,people,animals,product,scene) in enumerate(SCENES):
  jobs.append(dict(id=identity,size=size,prompt=COMMERCE+(WHITE if i<16 else '')+scene,
   scenario_family='commerce-v2-'+identity,people_requested=people,animals_requested=animals,
   product=product,brand_requested=brand,background_requested='white' if i<16 else 'context',
   crop_challenge='Retain whole faces, useful product silhouette and physical brand text.',synthetic=True,training_eligible=False))
 for identity,size,people,scene in CANDIDS:
  jobs.append(dict(id=identity,size=size,prompt='''Create one photorealistic amateur iPhone-style candid photograph in a normal smartphone-camera photo ratio. It should look like an average person's real snapshot: ordinary imperfect framing, believable proportions, skin pores, everyday fabrics, mild phone sharpening, honest lighting, no studio polish or cinematic color grade. A single coherent scene, not a collage. Nobody is a celebrity. No watermark or text overlay.\n'''+scene,
   scenario_family='smartphone-v2-'+identity,people_requested=people,animals_requested=1 if identity in ('birthday-garden','birthday-living-room','vacation-campsite') else 0,
   product='amateur-smartphone-candid',brand_requested=None,background_requested='context',
   crop_challenge='Complete faces at mixed depths and heights; retain candid story.',synthetic=True,training_eligible=False))
 assert len(jobs)==32 and sum(j['background_requested']=='white' for j in jobs)==16
 return jobs
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('output',type=Path);a=p.parse_args()
 with a.output.open('x') as f:json.dump(plan(),f,indent=2);f.write('\n')
